// Загрузка звезд из каталога Stars.csv с нормализацией смещения полей
void __fastcall TFormViewerHYG::LoadStarsCSV(String filename)
{
    m_stars.clear();
    FILE* fp = fopen(AnsiString(filename).c_str(), "r");
    if (!fp) return;

    char line[1024];
    if (!fgets(line, sizeof(line), fp)) {
        fclose(fp);
        return;
    }

    int offset = (strstr(line, "proper_ru") != NULL) ? 1 : 0;
    char fBuf[64];

    while (fgets(line, sizeof(line), fp)) {
        StarCatalogRecord star;
        memset(&star, 0, sizeof(star));

        GetField(line, 0, fBuf, sizeof(fBuf));
        star.id = atoi(fBuf);

        GetField(line, 6, fBuf, sizeof(fBuf));
        strncpy(star.proper, fBuf, sizeof(star.proper) - 1);

        GetField(line, 13 + offset, fBuf, sizeof(fBuf));
        star.mag = (float)atof(fBuf);

        GetField(line, 14 + offset, fBuf, sizeof(fBuf));
        star.absmag = (float)atof(fBuf);

        GetField(line, 15 + offset, fBuf, sizeof(fBuf));
        char sc = (fBuf[0] != '\0') ? (char)toupper(fBuf[0]) : 'G';
        star.spectClass = sc;

        GetField(line, 17 + offset, fBuf, sizeof(fBuf));
        star.x = (float)atof(fBuf);
        GetField(line, 18 + offset, fBuf, sizeof(fBuf));
        star.y = (float)atof(fBuf);
        GetField(line, 19 + offset, fBuf, sizeof(fBuf));
        star.z = (float)atof(fBuf);

        star.curX = star.x; star.curY = star.y; star.curZ = star.z;

        GetField(line, 20 + offset, fBuf, sizeof(fBuf));
        star.vx = (float)atof(fBuf);
        GetField(line, 21 + offset, fBuf, sizeof(fBuf));
        star.vy = (float)atof(fBuf);
        GetField(line, 22 + offset, fBuf, sizeof(fBuf));
        star.vz = (float)atof(fBuf);

        // Гарвардская шкала спектральных цветов OBAFGKM
        switch (sc) {
            case 'O': star.r = 0.0f;   star.g = 0.8f;  star.b = 1.0f;   break; // Blue
            case 'B': star.r = 0.6f;   star.g = 0.85f; star.b = 1.0f;   break; // Sky blue
            case 'A': star.r = 1.0f;   star.g = 1.0f;  star.b = 1.0f;   break; // White
            case 'F': star.r = 1.0f;   star.g = 1.0f;  star.b = 0.7f;   break; // Yellow-white
            case 'G': star.r = 1.0f;   star.g = 1.0f;  star.b = 0.15f;  break; // Yellow (Sol)
            case 'K': star.r = 1.0f;   star.g = 0.55f; star.b = 0.1f;   break; // Orange
            case 'M': star.r = 1.0f;   star.g = 0.2f;  star.b = 0.1f;   break; // Red
            default:  star.r = 0.9f;   star.g = 0.9f;  star.b = 0.9f;   break;
        }
        m_stars.push_back(star);
    }
    fclose(fp);
    m_simulatedYears = 0.0;
}

// Моделирование динамики собственного движения звезд во времени
void __fastcall TFormViewerHYG::GLCadencer1Progress(TObject *Sender, const double deltaTime, const double newTime)
{
    if (m_bDynamicsActive && !m_stars.empty()) {
        double dt = deltaTime;
        if (dt > 0.05) dt = 0.05; // ограничение шага для численной стабильности
        double dtYears = dt * (double)m_timeScale; // m_timeScale = 100 000 лет/сек
        m_simulatedYears += dtYears;

        for (size_t i = 0; i < m_stars.size(); i++) {
            m_stars[i].curX += m_stars[i].vx * (float)dtYears;
            m_stars[i].curY += m_stars[i].vy * (float)dtYears;
            m_stars[i].curZ += m_stars[i].vz * (float)dtYears;
        }

        if (Points1->Checked) {
            DrawCatalogStars();
        }

        if (StatusBar1->Panels->Count > 2) {
            StatusBar1->Panels->Items[2]->Text = 
                "Dynamics: ON (+" + IntToStr((int)m_simulatedYears) + " yrs)";
        }
    }
    GLSceneViewer1->Invalidate();
}

// Обновление отображения записей каталога в TListView с фильтрацией
void __fastcall TFormStarsCSV::PopulateListView()
{
    lvStars->Items->BeginUpdate();
    lvStars->Items->Clear();

    int filterClassIdx = cbClassFilter->ItemIndex;
    char targetClass = 0;
    switch (filterClassIdx) {
        case 1: targetClass = 'O'; break;
        case 2: targetClass = 'B'; break;
        case 3: targetClass = 'A'; break;
        case 4: targetClass = 'F'; break;
        case 5: targetClass = 'G'; break;
        case 6: targetClass = 'K'; break;
        case 7: targetClass = 'M'; break;
        default: targetClass = 0;   break;
    }

    AnsiString searchStr = AnsiString(edtSearch->Text).Trim().LowerCase();
    bool hasSearch = (searchStr.Length() > 0);

    const size_t maxDisplay = 2000;
    size_t displayed = 0;

    for (size_t i = 0; i < m_csvStars.size(); i++) {
        const CSVStarItem& s = m_csvStars[i];

        if (targetClass != 0 && s.spectClass != targetClass) continue;
        if (hasSearch && s.proper.LowerCase().Pos(searchStr) == 0) continue;

        TListItem* item = lvStars->Items->Add();
        item->Caption = IntToStr(s.id);
        item->SubItems->Add(s.proper.IsEmpty() ? AnsiString("-") : s.proper);
        item->SubItems->Add(s.spect.IsEmpty() ? AnsiString("-") : s.spect);
        item->SubItems->Add(AnsiString(s.spectClass));
        item->SubItems->Add(FormatFloat("0.00", s.mag));
        item->SubItems->Add(FormatFloat("0.00", s.absmag));
        item->SubItems->Add(FormatFloat("0.0", s.dist));
        item->SubItems->Add(FormatFloat("0.000", s.x));
        item->SubItems->Add(FormatFloat("0.000", s.y));
        item->SubItems->Add(FormatFloat("0.000", s.z));
        item->SubItems->Add(FormatFloat("0.000000", s.vx));
        item->SubItems->Add(FormatFloat("0.000000", s.vy));
        item->SubItems->Add(FormatFloat("0.000000", s.vz));

        if (++displayed >= maxDisplay) break;
    }
    lvStars->Items->EndUpdate();
    StatusBarCSV->Panels->Items[1]->Text = 
        "Показано записей: " + IntToStr((int)displayed) + " из " + IntToStr((int)m_csvStars.size());
}
